const newestEventSeq = `-- name: NewestEventSeq :one
SELECT CAST(COALESCE(MAX(seq), 0) AS INTEGER) AS seq FROM events
`

func (q *Queries) NewestEventSeq(ctx context.Context) (int64, error) {
	row := q.db.QueryRowContext(ctx, newestEventSeq)
	var seq int64
	err := row.Scan(&seq)
	return seq, err
}

const oldestEventSeq = `-- name: OldestEventSeq :one
SELECT CAST(COALESCE(MIN(seq), 0) AS INTEGER) AS seq FROM events
`

func (q *Queries) OldestEventSeq(ctx context.Context) (int64, error) {
	row := q.db.QueryRowContext(ctx, oldestEventSeq)
	var seq int64
	err := row.Scan(&seq)
	return seq, err
}

const pruneEvents = `-- name: PruneEvents :exec
DELETE FROM events WHERE events.at < ? AND events.seq < (SELECT MAX(newest.seq) FROM events AS newest)
`

func (q *Queries) PruneEvents(ctx context.Context, at int64) error {
	_, err := q.db.ExecContext(ctx, pruneEvents, at)
	return err
}

